"""Show the key generated by the FPGA in a key session (scripts/hw/soc_key.tcl).

    python scripts/show_key.py build/runs/<run>/key_base.txt

The FPGA has no way to output its key. The host chose the enrolment secret (the BCH
messages), and the helper data is public, so the golden model can recompute the enrolled
PUF response w and the key K = KDF(w). The script then checks this key against what the
chip itself produced:
    * the KCV in the helper data (computed by the FPGA from its key)
    * the MAC tags the FPGA returned for random challenges, before and after a reset
Matching values prove that the key inside the chip is exactly the key printed here.
Exit code 0 only when every check passes.
"""

import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)

from model import bch, fuzzy_extractor as fe          # noqa: E402
from model.bitutils import int_to_bits, bits_to_int   # noqa: E402

REP = 3                                   # repetition factor of the SoC (rtl/top/top_soc.v)
PARAMS = fe.FEParams(rep=REP)


def words_int(words):
    return sum(int(w, 16) << (32 * i) for i, w in enumerate(words))


def bits_text(st):
    names = [(6, "kcv_ok"), (5, "ecc_ok"), (4, "key_valid"), (3, "locked"), (2, "cmd_err")]
    return " ".join("{}={}".format(n, (st >> b) & 1) for b, n in names)


def read_record(path):
    rec = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            parts = line.split()
            if parts:
                rec.setdefault(parts[0], []).append(parts[1:])
    return rec


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    rec = read_record(sys.argv[1])
    one = lambda k: rec[k][0]
    mode = one("mode")[0]
    ok_all = True

    def check(label, ok, detail=""):
        nonlocal ok_all
        ok_all &= ok
        print("  [{}] {}{}".format("PASS" if ok else "FAIL", label, ("  " + detail) if detail else ""))

    print()
    print("=" * 78)
    print(" RO-PUF key session: {} RO-PUF ({})".format(
        "configurable" if mode == "cfg" else "baseline", os.path.abspath(sys.argv[1])))
    print("=" * 78)
    print(" die temperature {} C -> {} C, switches SW3..SW0 = {:04b}".format(
        one("temperature_c")[0], one("temperature_end_c")[0], int(one("switches")[0], 16)))

    st_enrol = int(one("enrol_status")[0], 16)
    if (st_enrol >> 2) & 1:                 # cmd_err: enrolment refused
        print("\n ENROL was not accepted ({}).".format(bits_text(st_enrol)))
        if (int(one("switches")[0], 16) >> 3) & 1:
            print(" SW3 (emulated one-time fuse) is ON, so enrolment is locked from reset.")
            print(" Turn SW3 off and run again.")
        sys.exit(1)

    # ---- what the host knows: enrolment messages and the public helper data
    msg = words_int(one("messages"))
    messages = [(msg >> (7 * i)) & 0x7F for i in range(PARAMS.n_blocks)]
    helper = one("helper")
    offset = int_to_bits(words_int(helper[0:4]), 128)[:PARAMS.used_bits]
    kcv_chip = int(helper[4], 16)

    # ---- golden model: c = Rep3(BCH(m)), w = offset XOR c, K = KDF(w)
    c = fe.encode_messages(messages, PARAMS)
    w = offset ^ c
    key = fe.derive_key(w)
    kcv_model = fe.key_check_value(key)

    print("\n STORED IN THE SoC (public helper data, 17 words in RAM)")
    print("   offset w XOR c  : {}  (words 3..0, {} bits used)".format(" ".join(helper[3::-1]), PARAMS.used_bits))
    print("   KCV             : {}".format(helper[4]))
    if mode == "cfg":
        print("   RO configuration: {}".format(" ".join(helper[5:17])))
    else:
        print("   RO configuration: (baseline: not used)")

    print("\n RECOMPUTED BY THE HOST (golden model, never read from the FPGA)")
    print("   BCH messages    : {}  (secret chosen at enrolment, {} x 7 bits)".format(
        " ".join("{:02x}".format(m) for m in messages), PARAMS.n_blocks))
    print("   BCH codewords   : {}".format(" ".join("{:04x}".format(bch.encode(m)) for m in messages)))
    print("   PUF response w  : {:023x}  ({} bits = {} BCH blocks x 15 x rep {})".format(
        bits_to_int(w), PARAMS.used_bits, PARAMS.n_blocks, REP))
    print()
    box = "  KEY  K = {:032x}  (128 bits)  ".format(key)
    print("   +" + "-" * len(box) + "+")
    print("   |" + box + "|")
    print("   +" + "-" * len(box) + "+")
    print("   KCV = SipHash(K, 'KCV')[31:0] = {:08x}".format(kcv_model))

    print("\n CHECKS AGAINST THE FPGA")
    check("enrolment accepted, chip locked itself afterwards", bool((st_enrol >> 3) & 1),
          bits_text(st_enrol))
    st = int(one("enrol_again_status")[0], 16)
    check("second enrolment refused (one-time lock)", bool((st >> 2) & 1) and bool((st >> 3) & 1), bits_text(st))
    check("FPGA KCV equals the KCV of this key", kcv_chip == kcv_model,
          "chip {:08x}, model {:08x}".format(kcv_chip, kcv_model))

    st = int(one("recon_status")[0], 16)
    check("reconstruction gives a valid key", bool((st >> 4) & 1), bits_text(st))
    n_ok = 0
    for chal, tag in [(e[0:2], e[2:4]) for e in rec["tag"]]:
        expect = fe.mac(key, words_int(chal))
        n_ok += words_int(tag) == expect
    check("MAC tags from the FPGA equal MAC(K, challenge)", n_ok == len(rec["tag"]),
          "{}/{} challenges".format(n_ok, len(rec["tag"])))
    for chal, tag in [(e[0:2], e[2:4]) for e in rec["tag"]]:
        print("         challenge {:016x} -> tag {:016x}".format(words_int(chal), words_int(tag)))

    st = int(one("field_status_after_reset")[0], 16)
    check("after SoC reset the key is gone", not (st >> 4) & 1, bits_text(st))
    st = int(one("field_recon_status")[0], 16)
    check("helper data restored, key reconstructed", bool((st >> 4) & 1), bits_text(st))
    n_ok = sum(words_int(e[2:4]) == fe.mac(key, words_int(e[0:2])) for e in rec["field_tag"])
    check("same key after reset (same MAC tags)", n_ok == len(rec["field_tag"]),
          "{}/{} challenges".format(n_ok, len(rec["field_tag"])))

    for (dev, st), (_, *ct) in zip(rec["other_device"], rec["other_device_tag"]):
        st = int(st, 16)
        tag_ok = words_int(ct[2:4]) == fe.mac(key, words_int(ct[0:2]))
        check("device {} (other RO array) cannot rebuild this key".format(dev),
              not (st >> 4) & 1 and not tag_ok, bits_text(st))

    print()
    print(" RESULT: {}".format("ALL CHECKS PASSED - the key above is the key inside the FPGA"
                               if ok_all else "SOME CHECKS FAILED"))
    print(" Note: K = KDF(w) is fixed by the PUF reading taken at enrolment. Re-enrolling")
    print(" usually gives the same key, but if an unstable response bit reads differently")
    print(" during enrolment the key changes. The ECC guarantees that every later")
    print(" reconstruction reproduces the key that was enrolled.")
    print("=" * 78)
    sys.exit(0 if ok_all else 1)


if __name__ == "__main__":
    main()
